function sourceFormatText(text, edits) {
  const chars = Array.from(text);
  let output = '', previous = 0;
  for (const [start,end,value] of edits) {
    output += chars.slice(previous,start).join('') + value;
    previous = end;
  }
  return output + chars.slice(previous).join('');
}
export function publicSourceFormatting(source, reading = source, workId = source?.work?.id) {
  const saved = sourceFormats[workId]?.[source?.id]?.find(view => view.id === reading?.id && view.sha256 === reading?.sha256);
  if (!saved || !Array.isArray(reading?.paragraphs) || saved.count !== reading.paragraphs.length) return {};
  const matches = ([index, id, fingerprint]) => reading.paragraphs[index]?.id === id
    && sourcePresentationMatches(reading.paragraphs[index].text, fingerprint);
  if (saved.facsimile && !saved.rows.every(matches)) return {};
  const passages = Object.fromEntries(saved.rows.filter(matches).map(([index,id,,fields]) => [id,
    Object.fromEntries(Object.entries(fields).map(([key,value]) => [key,
      Array.isArray(value) ? sourceFormatText(reading.paragraphs[index].text,value) : value]))]));
  const chapter = saved.facsimile ? {beautiful_typeset:true} : {};
  if (saved.opening_id && passages[saved.opening_id]) chapter.beautiful_opening_passage_id = saved.opening_id;
  return {chapter, passages};
}
export function publicSourceDisplayTitle(source, workId = source?.work?.id) {
  const saved = sourceFormats[workId]?.[source?.id]?.find(view => view.title && view.id === source.id && view.sha256 === source.sha256);
  return saved && sourcePresentationMatches(source.text, saved.body) ? saved.title : '';
}
